import React, { useState, useEffect } from "react";
import {
  Box,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Typography,
  Container,
  InputAdornment,
  Collapse,
  Grid,
  IconButton,
  TablePagination,
  CircularProgress,
  FormHelperText,
} from "@mui/material";
import {
  Person as PersonIcon,
  PersonAdd as PersonAddIcon,
  EditDocument as EditDocumentIcon,
  Delete as DeleteIcon,
  Search as SearchIcon,
  FilterList as FilterIcon,
  AccessTime as TimeIcon,
  Visibility as VisibilityIcon,
  VisibilityOff as VisibilityOffIcon,
  Search,
} from "@mui/icons-material";
import Swal from "sweetalert2";
import { useNavigate } from "react-router-dom";
import { apiRequest } from "../utils/apiRequest";
import { API } from "../api/endpoints";
function TabPanel({ children, value, index, ...other }) {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`tabpanel-${index}`}
      aria-labelledby={`tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

const UserManagement = () => {
  const [tabValue, setTabValue] = useState(0);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);
  // const [timeFilter, setTimeFilter] = useState("Last 1 hour");
  const [filters, setFilters] = useState({
    role: "",
    department: "",
    location: "",
  });
  const [formData, setFormData] = useState({
    name: "",
    username: "",
    email: "",
    password: "",
    confirmPassword: "",
    role: "",
    location_id: "",
    department_id: "",
    mobile: "",
  });
  const [errors, setErrors] = useState({});
  const [users, setUsers] = useState([]);
  const [page, setPage] = useState(0); // API uses 1-based indexing, so adjust accordingly
  const [rowsPerPage, setRowsPerPage] = useState(10); // Match API's per_page default
  const [totalUsers, setTotalUsers] = useState(0);
  const [loading, setLoading] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [selectedUserId, setSelectedUserId] = useState(null);
  const [locations, setLocations] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [buttonLoading, setButtonLoading] = useState(false);
  const [accountActionUserId, setAccountActionUserId] = useState(null);
  const [noDataMessage, setNoDataMessage] = useState("No data available");

  const userRole =
    typeof window !== "undefined" ? localStorage.getItem("role") : "";
  const isSuperAdmin = userRole === "super_admin";
  const isAdminPanelUser = userRole === "admin" || userRole === "super_admin";

  const navigate = useNavigate();
  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 1500,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
    customClass: {
      container: "swal-toast-container",
      popup: "swal-toast-popup",
    },
  });

  // Inject custom styles
  useEffect(() => {
    const styleSheet = document.createElement("style");
    styleSheet.textContent = `
      .swal-toast-container {
        z-index: 9999 !important;
      }
      .swal-toast-popup {
        font-family: 'Inter', sans-serif;
        font-size: 14px;
      }
      .swal2-popup .swal-user-disable-actions {
        gap: 14px !important;
        justify-content: center !important;
      }
      .swal2-popup .swal-user-disable-confirm {
        border-radius: 6px !important;
        padding: 10px 28px !important;
        background: #f97316 !important;
        color: #fff !important;
        border: none !important;
      }
      .swal2-popup .swal-user-disable-cancel {
        border-radius: 6px !important;
        padding: 10px 28px !important;
        background: #fff !important;
        color: #333 !important;
        border: 1px solid #333 !important;
      }
    `;
    document.head.appendChild(styleSheet);
    return () => {
      document.head.removeChild(styleSheet); // Cleanup on unmount
    };
  }, []);

  // Get token from localStorage
  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  // Fetch user list with pagination
  // const fetchUsers = async () => {
  //   setLoading(true);
  //   try {
  //     const response = await axios.get("/admin/user/list", {
  //       params: {
  //         paginate: true,
  //         page: page + 1, // API uses 1-based indexing
  //         per_page: rowsPerPage,
  //         search: searchQuery,
  //         role: filters.role,
  //         department: filters.department,
  //         location: filters.location,
  //       },
  //       headers: {
  //         Authorization: `Bearer ${token}`,
  //       },
  //     });
  //     setUsers(response.data.data.data);
  //     setTotalUsers(response.data.data.total);
  //   } catch (error) {
  //     setUsers([]);
  //     setTotalUsers(0);
  //   } finally {
  //     setLoading(false);
  //   }
  // };
  const fetchUsers = async () => {
    if (!token) {
      console.error("Authentication token is missing");
      setUsers([]);
      setTotalUsers(0);
      setNoDataMessage("Authentication token is missing");
      return;
    }

    setLoading(true);

    try {
      const response = await apiRequest({
        ...API.usersList,
        params: {
          paginate: true,
          page: page + 1,
          per_page: rowsPerPage,
          ...(searchQuery && { search: searchQuery }),
          ...(filters.role && { role: filters.role }),
          ...(filters.department_id && {
            department_id: filters.department_id,
          }),
          ...(filters.location_id && {
            location_id: filters.location_id,
          }),
        },
      });

      if (response?.success) {
        setUsers(response.data?.data || []);
        setTotalUsers(response.data?.total || 0);
        setNoDataMessage("No data available");
      } else if (
        response?.message === "No data found." &&
        response?.data?.error === "No data found"
      ) {
        setUsers([]);
        setTotalUsers(0);
        setNoDataMessage("No users found for the selected filters");
      } else {
        setUsers([]);
        setTotalUsers(0);
        setNoDataMessage("Failed to fetch users");

        console.error("Error fetching users:", response?.message);
      }
    } catch (error) {
      setUsers([]);
      setTotalUsers(0);

      setNoDataMessage(
        error?.message === "No data found."
          ? "No users found for the selected filters"
          : error?.message || "Failed to fetch users",
      );

      console.error("Error fetching users:", error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch locations and departments
  const fetchLocationsAndDepartments = async () => {
    try {
      const locationsResponse = await apiRequest({ ...API.locationsList });
      const departmentsResponse = await apiRequest({
        ...API.departmentsList,
      });
      setLocations(locationsResponse.data);
      setDepartments(departmentsResponse.data);
    } catch (error) {
      setLocations([]);
      setDepartments([]);
    }
  };

  useEffect(() => {
    fetchUsers();
    fetchLocationsAndDepartments();
  }, [page, rowsPerPage, searchQuery, filters]);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
    setEditMode(false);
    setFormData({
      name: "",
      username: "",
      email: "",
      password: "",
      confirmPassword: "",
      role: "",
      location_id: "",
      department_id: "",
      mobile: "",
    });
    setErrors({});
  };

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
    setErrors((prev) => ({
      ...prev,
      [name]: "",
    }));
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = "Name is required";
    if (!editMode) {
      if (!formData.username.trim())
        newErrors.username = "Username is required";
      if (!formData.email.trim()) newErrors.email = "Email is required";
      else if (!/\S+@\S+\.\S+/.test(formData.email))
        newErrors.email = "Invalid email format";
      if (!formData.password) newErrors.password = "Password is required";
      else if (formData.password.length < 6)
        newErrors.password = "Password must be at least 6 characters";
      if (!formData.confirmPassword)
        newErrors.confirmPassword = "Confirm password is required";
      else if (formData.password !== formData.confirmPassword)
        newErrors.confirmPassword = "Passwords do not match";
    }
    if (!formData.role) newErrors.role = "Role is required";
    if (!formData.location_id) newErrors.location_id = "Location is required";
    if (!formData.department_id)
      newErrors.department_id = "Department is required";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSaveChanges = async () => {
    if (!validateForm()) return;

    setButtonLoading(true);

    const data = new FormData();

    data.append("name", formData.name);
    data.append("username", formData.username);
    data.append("email", formData.email);
    data.append("password", formData.password);
    data.append("role", formData.role);
    data.append("location_id", formData.location_id);
    data.append("department_id", formData.department_id);
    if (formData.mobile?.trim()) {
      data.append("mobile", formData.mobile.trim());
    }

    try {
      const response = await apiRequest({
        ...(editMode
          ? {
              ...API.editUser(selectedUserId),
            }
          : {
              ...API.addUser,
            }),

        method: "POST",
        data,
      });

      Toast.fire({
        icon: "success",
        title: "Success",
        text: response?.message || (editMode ? "User updated" : "User created"),
      });

      setTabValue(0);
      fetchUsers();
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: "Error",
        text: error?.message || "Failed to save user",
      });
    } finally {
      setButtonLoading(false);
    }
  };

  const handleCancel = () => {
    setEditMode(false);
    setFormData({
      name: "",
      username: "",
      email: "",
      password: "",
      confirmPassword: "",
      role: "standard",
      location_id: "",
      department_id: "",
      mobile: "",
    });
    setErrors({});
  };

  const handleEdit = async (id) => {
    try {
      const response = await apiRequest({
        ...API.userDetails(id),
      });

      const user = response?.data;

      setFormData({
        name: user?.name || "",
        username: user?.username || "",
        email: user?.email || "",
        role: user?.role || "",
        location_id: user?.location_id || "",
        department_id: user?.department_id || "",
        mobile: user?.mobile || user?.phone_secondary || "",
        password: "",
        confirmPassword: "",
      });

      setSelectedUserId(id);
      setEditMode(true);
      setTabValue(1);
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: "Error",
        text: error?.message || "Failed to fetch user details",
      });
    }
  };

  const isUserDisabled = (user) =>
    user?.is_active === 0 ||
    user?.is_active === false ||
    user?.status === "disabled" ||
    user?.disabled === true;

  const getDepartmentName = (user) =>
    user?.department?.name ||
    departments.find((d) => d.id === user?.department_id)?.name ||
    "N/A";

  const getLocationName = (user) =>
    user?.location?.name ||
    locations.find((l) => l.id === user?.location_id)?.name ||
    "N/A";

  const getRowNumber = (index) => page * rowsPerPage + index + 1;

  const handleToggleAccount = async (user) => {
    if (!isSuperAdmin) return;
    const enabling = isUserDisabled(user);
    const result = await Swal.fire({
      title: enabling ? "Re-enable this account?" : "Disable this account?",
      text: enabling
        ? "This user will be able to sign in again."
        : "This user will not be able to sign in. Their data is kept in the system.",
      icon: "warning",
      showCancelButton: true,
      reverseButtons: true,
      confirmButtonText: enabling ? "Enable account" : "Disable account",
      cancelButtonText: "Cancel",
      buttonsStyling: false,
      customClass: {
        actions: "swal-user-disable-actions",
        confirmButton: "swal-user-disable-confirm",
        cancelButton: "swal-user-disable-cancel",
      },
    });
    if (!result.isConfirmed) return;

    setAccountActionUserId(user.id);
    try {
      await apiRequest({
        ...API.editUser(user.id),
        method: "POST",
        data: { is_active: enabling ? 1 : 0 },
      });
      Toast.fire({
        icon: "success",
        title: enabling ? "Account enabled" : "Account disabled",
      });
      fetchUsers();
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: error?.message || "Failed to update account status",
      });
    } finally {
      setAccountActionUserId(null);
    }
  };

  const handleDelete = (id) => {
    Swal.fire({
      title: "Are you sure?",
      text: "You won't be able to revert this!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#43B02A",
      cancelButtonColor: "#C92A20",
      confirmButtonText: "Yes, delete it!",
      cancelButtonText: "No, cancel",
      customClass: {
        container: "swal-toast-container",
        popup: "swal-toast-popup",
      },
    }).then(async (result) => {
      if (result.isConfirmed) {
        try {
          const response = await apiRequest({
            ...API.deleteUser(id),
          });

          Toast.fire({
            icon: "success",
            title: "Deleted",
            text: response?.message || "User deleted successfully",
          });

          fetchUsers();
        } catch (error) {
          Toast.fire({
            icon: "error",
            title: "Error",
            text: error?.message || "Failed to delete user",
          });
        }
      }
    });
  };
  const handleFilterChange = (name, value) => {
    setFilters((prev) => ({
      ...prev,
      [name]: value,
    }));
    setPage(0);
  };

  const clearFilters = () => {
    setFilters({ role: "", department_id: "", location_id: "" });
    setPage(0);
    setFilterOpen(false);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage); // 0-based index for state, API uses 1-based
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  return (
    <Grid
      container
      rowSpacing={{ xs: 1, sm: 2, md: 2 }}
      columnSpacing={{ xs: 1, sm: 2, md: 2 }}
    >
      {/* Header with Search */}
      <Grid size={{ xs: 12, sm: 12, md: 12, lg: 12, xl: 12 }}>
        <Box sx={{ mb: 2 }}>
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: 2,
              mb: 2,
            }}
          >
            <TextField
              placeholder="Search or jump to..."
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setPage(0);
              }}
              size="small"
              sx={{
                "& .MuiOutlinedInput-root": {
                  borderRadius: 8,
                  backgroundColor: "#fff",
                  "& fieldset": { borderColor: "#e0e0e0" },
                  "&:hover fieldset": { borderColor: "#bdbdbd" },
                  "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                  "& input": {
                    padding: { xs: "6px 10px", sm: "8px 12px" },
                    fontSize: { xs: "0.75rem", sm: "0.875rem" },
                  },
                },
              }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon
                      sx={{ color: "#666", fontSize: { xs: 18, sm: 20 } }}
                    />
                  </InputAdornment>
                ),
              }}
            />
            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
              <Button
                variant="outlined"
                startIcon={<FilterIcon />}
                onClick={() => setFilterOpen(!filterOpen)}
                size="small"
                sx={{
                  backgroundColor: "#fff",
                  borderColor: "#e0e0e0",
                  color: "#333",
                  borderRadius: 8,
                  padding: { xs: "4px 8px", sm: "6px 12px" },
                  textTransform: "none",
                  fontWeight: 500,
                  "&:hover": {
                    borderColor: "#bdbdbd",
                    backgroundColor: "rgba(0, 0, 0, 0.04)",
                  },
                }}
              >
                Filter
              </Button>
            </Box>
          </Box>
          <Collapse in={filterOpen}>
            <Paper
              sx={{
                p: 3,
                mt: 2,
                borderRadius: 3,
                bgcolor: "#f8f9fa",
                boxShadow: "0 4px 12px rgba(0,0,0,0.1)",
              }}
            >
              <Grid container spacing={2}>
                <Grid item xs={12} md={4}>
                  <FormControl fullWidth size="small" variant="outlined">
                    <InputLabel id="role-filter-label" shrink={true}>
                      Role
                    </InputLabel>
                    <Select
                      labelId="role-filter-label"
                      value={filters.role}
                      onChange={(e) =>
                        handleFilterChange("role", e.target.value)
                      }
                      label="Role"
                      displayEmpty
                      renderValue={(selected) => selected || "All Roles"}
                      sx={{
                        borderRadius: 8,
                        "& .MuiSelect-select": {
                          fontSize: { xs: "0.75rem", sm: "0.875rem" },
                        },
                        "& fieldset": { borderColor: "#e0e0e0" },
                        "&:hover fieldset": { borderColor: "#4CAF50" },
                        "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                      }}
                    >
                      <MenuItem value="">All Roles</MenuItem>
                      <MenuItem value="standard">Standard</MenuItem>
                      <MenuItem value="department_head">
                        Department Head
                      </MenuItem>
                      <MenuItem value="executive">Executive</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12} md={4}>
                  <FormControl fullWidth size="small" variant="outlined">
                    <InputLabel id="department-filter-label" shrink={true}>
                      Department
                    </InputLabel>
                    <Select
                      labelId="department-filter-label"
                      value={filters.department_id}
                      onChange={(e) =>
                        handleFilterChange("department_id", e.target.value)
                      }
                      label="Department"
                      displayEmpty
                      renderValue={(selected) =>
                        selected
                          ? departments.find((d) => d.id === selected)?.name ||
                            "All Departments"
                          : "All Departments"
                      }
                      sx={{
                        borderRadius: 8,
                        "& .MuiSelect-select": {
                          fontSize: { xs: "0.75rem", sm: "0.875rem" },
                        },
                        "& fieldset": { borderColor: "#e0e0e0" },
                        "&:hover fieldset": { borderColor: "#4CAF50" },
                        "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                      }}
                    >
                      <MenuItem value="">All Departments</MenuItem>
                      {departments.map((dept) => (
                        <MenuItem key={dept.id} value={dept.id}>
                          {dept.name}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>
                <Grid item xs={12} md={4}>
                  <FormControl fullWidth size="small" variant="outlined">
                    <InputLabel id="location-filter-label" shrink={true}>
                      Location
                    </InputLabel>
                    <Select
                      labelId="location-filter-label"
                      value={filters.location_id}
                      onChange={(e) =>
                        handleFilterChange("location_id", e.target.value)
                      }
                      label="Location"
                      displayEmpty
                      renderValue={(selected) =>
                        selected
                          ? locations.find((l) => l.id === selected)?.name ||
                            "All Locations"
                          : "All Locations"
                      }
                      sx={{
                        borderRadius: 8,
                        "& .MuiSelect-select": {
                          fontSize: { xs: "0.75rem", sm: "0.875rem" },
                        },
                        "& fieldset": { borderColor: "#e0e0e0" },
                        "&:hover fieldset": { borderColor: "#4CAF50" },
                        "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
                      }}
                    >
                      <MenuItem value="">All Locations</MenuItem>
                      {locations.map((loc) => (
                        <MenuItem key={loc.id} value={loc.id}>
                          {loc.name}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>
              </Grid>
              <Box
                sx={{
                  display: "flex",
                  justifyContent: "flex-end",
                  gap: 1,
                  mt: 2,
                }}
              >
                <Button
                  size="small"
                  onClick={clearFilters}
                  sx={{
                    borderColor: "#e0e0e0",
                    color: "#333",
                    textTransform: "none",
                    fontSize: { xs: "0.75rem", sm: "0.875rem" },
                    px: 3,
                    py: 1,
                    borderRadius: 8,
                    "&:hover": {
                      borderColor: "#bdbdbd",
                      bgcolor: "rgba(0,0,0,0.04)",
                    },
                  }}
                >
                  Clear Filters
                </Button>
                <Button
                  size="small"
                  variant="contained"
                  onClick={() => setFilterOpen(false)}
                  sx={{
                    backgroundColor: "#43B02A",
                    "&:hover": { backgroundColor: "#3a9624" },
                    textTransform: "none",
                    fontSize: { xs: "0.75rem", sm: "0.875rem" },
                    px: 3,
                    py: 1,
                    borderRadius: 8,
                    boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
                  }}
                >
                  Apply
                </Button>
              </Box>
            </Paper>
          </Collapse>
        </Box>
        <Paper
          sx={{
            width: "100%",
            borderRadius: 2,
            boxShadow: 1,
            overflow: "hidden",
          }}
        >
          <Box sx={{ borderBottom: "1px solid #e0e0e0" }}>
            <Tabs
              value={tabValue}
              onChange={handleTabChange}
              sx={{
                "& .MuiTab-root": {
                  textTransform: "none",
                  fontWeight: 500,
                  minHeight: 48,
                  borderRadius: 1,
                },
                "& .Mui-selected": {
                  backgroundColor: "#F97316 !important",
                  color: "white !important",
                },
                "& .MuiTabs-indicator": { backgroundColor: "#fff", height: 2 },
              }}
            >
              <Tab
                icon={<PersonIcon />}
                label="Users List"
                iconPosition="start"
                sx={{ gap: 1 }}
              />
              <Tab
                // icon={<PersonAddIcon />}
                icon={editMode ? <EditDocumentIcon /> : <PersonAddIcon />}
                label={editMode ? "Update User" : "Create User"}
                iconPosition="start"
                sx={{ gap: 1 }}
              />
            </Tabs>
          </Box>

          <TabPanel value={tabValue} index={0}>
            <TableContainer sx={{ overflowX: "auto" }}>
              <Table size="small" sx={{ minWidth: isSuperAdmin ? 960 : 720 }}>
                <TableHead>
                  <TableRow>
                    {isSuperAdmin ? (
                      <>
                        <TableCell sx={{ fontWeight: "bold" }}>No.</TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>Email</TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>
                          Username
                        </TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>Role</TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>
                          Department
                        </TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>
                          Location
                        </TableCell>
                        <TableCell
                          sx={{
                            fontWeight: "bold",
                            minWidth: 200,
                            whiteSpace: "nowrap",
                          }}
                        >
                          Actions
                        </TableCell>
                      </>
                    ) : (
                      <>
                        <TableCell sx={{ fontWeight: "bold" }}>#</TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>Name</TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>Email</TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>
                          Username
                        </TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>Role</TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>
                          Department
                        </TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>
                          Location
                        </TableCell>
                        <TableCell sx={{ fontWeight: "bold" }}>
                          Actions
                        </TableCell>
                      </>
                    )}
                  </TableRow>
                </TableHead>
                <TableBody>
                  {loading ? (
                    <TableRow>
                      <TableCell colSpan={isSuperAdmin ? 7 : 8} align="center">
                        Loading...
                      </TableCell>
                    </TableRow>
                  ) : Array.isArray(users) && users.length > 0 ? (
                    users.map((user, index) =>
                      isSuperAdmin ? (
                        <TableRow key={user.id} hover>
                          <TableCell>{getRowNumber(index)}</TableCell>
                          <TableCell>{user.email || "N/A"}</TableCell>
                          <TableCell>{user.username || "N/A"}</TableCell>
                          <TableCell>{user.role || "N/A"}</TableCell>
                          <TableCell>{getDepartmentName(user)}</TableCell>
                          <TableCell>{getLocationName(user)}</TableCell>
                          <TableCell sx={{ whiteSpace: "nowrap" }}>
                            <Box
                              sx={{
                                display: "inline-flex",
                                gap: 0.75,
                                alignItems: "center",
                                flexWrap: "nowrap",
                              }}
                            >
                              <Button
                                variant="outlined"
                                size="small"
                                color={
                                  isUserDisabled(user) ? "success" : "error"
                                }
                                disabled={accountActionUserId === user.id}
                                onClick={() => handleToggleAccount(user)}
                                sx={{
                                  textTransform: "none",
                                  borderRadius: 3,
                                  fontSize: "12px",
                                  flexShrink: 0,
                                }}
                              >
                                {accountActionUserId === user.id ? (
                                  <CircularProgress size={14} />
                                ) : isUserDisabled(user) ? (
                                  "Enable"
                                ) : (
                                  "Disable"
                                )}
                              </Button>
                              <Button
                                variant="contained"
                                size="small"
                                onClick={() => handleEdit(user.id)}
                                sx={{
                                  backgroundColor: "#3B82F6",
                                  textTransform: "none",
                                  borderRadius: 3,
                                  fontSize: "12px",
                                  flexShrink: 0,
                                  "&:hover": { backgroundColor: "#3B82F6" },
                                }}
                              >
                                Edit
                              </Button>
                              <IconButton
                                size="small"
                                onClick={() => handleDelete(user.id)}
                                sx={{
                                  backgroundColor: "#C92A20",
                                  color: "#fff",
                                  borderRadius: 3,
                                  width: 32,
                                  height: 32,
                                  flexShrink: 0,
                                }}
                              >
                                <DeleteIcon fontSize="small" />
                              </IconButton>
                            </Box>
                          </TableCell>
                        </TableRow>
                      ) : (
                        <TableRow key={user.id} hover>
                          <TableCell>{getRowNumber(index)}</TableCell>
                          <TableCell>{user.name}</TableCell>
                          <TableCell>{user.email}</TableCell>
                          <TableCell>{user.username}</TableCell>
                          <TableCell>{user.role}</TableCell>
                          <TableCell>{getDepartmentName(user)}</TableCell>
                          <TableCell>{getLocationName(user)}</TableCell>
                          <TableCell>
                            <Box sx={{ display: "flex", gap: 1 }}>
                              <Button
                                variant="contained"
                                size="small"
                                onClick={() => handleEdit(user.id)}
                                sx={{
                                  backgroundColor: "#3B82F6",
                                  textTransform: "none",
                                  borderRadius: 3,
                                  fontSize: "12px",
                                }}
                              >
                                Edit
                              </Button>
                              <IconButton
                                size="small"
                                onClick={() => handleDelete(user.id)}
                                sx={{
                                  backgroundColor: "#C92A20",
                                  color: "#fff",
                                  borderRadius: 3,
                                }}
                              >
                                <DeleteIcon fontSize="small" />
                              </IconButton>
                            </Box>
                          </TableCell>
                        </TableRow>
                      ),
                    )
                  ) : (
                    <TableRow>
                      <TableCell colSpan={isSuperAdmin ? 7 : 8} align="center">
                        {noDataMessage}
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </Table>
            </TableContainer>
            <TablePagination
              rowsPerPageOptions={[5, 10, 25]}
              component="div"
              count={totalUsers}
              rowsPerPage={rowsPerPage}
              page={page}
              onPageChange={handleChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
            />
          </TabPanel>

          <TabPanel value={tabValue} index={1}>
            <Grid container spacing={3} sx={{ maxWidth: 600, mx: "auto" }}>
              <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                <Typography
                  variant="subtitle1"
                  sx={{ mb: 1, fontWeight: "medium" }}
                >
                  Name
                </Typography>
                <TextField
                  fullWidth
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  variant="outlined"
                  size="small"
                  error={!!errors.name}
                  helperText={errors.name}
                  sx={{
                    "& .MuiOutlinedInput-root": {
                      borderRadius: "4px",
                      fontFamily: "Speedee",
                    },
                    "& .MuiInputLabel-root": { fontFamily: "Speedee" },
                    "& .MuiInputBase-input.Mui-disabled": {
                      color: "black",
                      WebkitTextFillColor: "black",
                      opacity: 1,
                    },
                    "& .MuiOutlinedInput-root.Mui-disabled .MuiOutlinedInput-notchedOutline":
                      {
                        borderColor: "rgba(0, 0, 0, 0.23)",
                      },
                  }}
                />
              </Grid>
              <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                <Typography
                  variant="subtitle1"
                  sx={{ mb: 1, fontWeight: "medium" }}
                >
                  Email
                </Typography>
                <TextField
                  fullWidth
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  variant="outlined"
                  size="small"
                  error={!!errors.email}
                  helperText={errors.email}
                  //  disabled={editMode}
                  sx={{
                    "& .MuiOutlinedInput-root": {
                      borderRadius: "4px",
                      fontFamily: "Speedee",
                    },
                    "& .MuiInputLabel-root": { fontFamily: "Speedee" },
                    "& .MuiInputBase-input.Mui-disabled": {
                      color: "black",
                      WebkitTextFillColor: "black",
                      opacity: 1,
                    },
                    "& .MuiOutlinedInput-root.Mui-disabled .MuiOutlinedInput-notchedOutline":
                      {
                        borderColor: "rgba(0, 0, 0, 0.23)",
                      },
                  }}
                />
              </Grid>

              <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                <Typography
                  variant="subtitle1"
                  sx={{ mb: 1, fontWeight: "medium" }}
                >
                  Username
                </Typography>
                <TextField
                  fullWidth
                  name="username"
                  value={formData.username}
                  onChange={handleInputChange}
                  variant="outlined"
                  size="small"
                  error={!!errors.username}
                  helperText={errors.username}
                  //   disabled={editMode}
                  sx={{
                    "& .MuiOutlinedInput-root": {
                      borderRadius: "4px",
                      fontFamily: "Speedee",
                    },
                    "& .MuiInputLabel-root": { fontFamily: "Speedee" },
                    "& .MuiInputBase-input.Mui-disabled": {
                      color: "black",
                      WebkitTextFillColor: "black",
                      opacity: 1,
                    },
                    "& .MuiOutlinedInput-root.Mui-disabled .MuiOutlinedInput-notchedOutline":
                      {
                        borderColor: "rgba(0, 0, 0, 0.23)",
                      },
                  }}
                />
              </Grid>
              <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                <Typography
                  variant="subtitle1"
                  sx={{ mb: 1, fontWeight: "medium" }}
                >
                  Role
                </Typography>
                <FormControl fullWidth size="small" variant="outlined">
                  <InputLabel>Role</InputLabel>
                  <Select
                    name="role"
                    value={formData.role}
                    onChange={handleInputChange}
                    label="Role"
                    error={!!errors.role}
                  >
                    {isSuperAdmin && <MenuItem value="admin">Admin</MenuItem>}
                    <MenuItem value="standard">
                      {isSuperAdmin ? "Standard User" : "Standard"}
                    </MenuItem>
                    <MenuItem value="department_head">Department Head</MenuItem>
                    <MenuItem value="executive">Executive</MenuItem>
                  </Select>
                  <FormHelperText error={!!errors.role}>
                    {errors.role || " "}
                  </FormHelperText>
                </FormControl>
              </Grid>

              {!editMode && (
                <>
                  <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                    <Typography
                      variant="subtitle1"
                      sx={{ mb: 1, fontWeight: "medium" }}
                    >
                      Password
                    </Typography>
                    <TextField
                      fullWidth
                      name="password"
                      type={showPassword ? "text" : "password"}
                      value={formData.password}
                      onChange={handleInputChange}
                      variant="outlined"
                      size="small"
                      error={!!errors.password}
                      helperText={errors.password}
                      sx={{
                        "& .MuiOutlinedInput-root": {
                          borderRadius: "4px",
                          fontFamily: "Speedee",
                        },
                        "& .MuiInputLabel-root": { fontFamily: "Speedee" },
                      }}
                      InputProps={{
                        endAdornment: (
                          <InputAdornment position="end">
                            <IconButton
                              onClick={() => setShowPassword(!showPassword)}
                              edge="end"
                            >
                              {showPassword ? (
                                <VisibilityOffIcon />
                              ) : (
                                <VisibilityIcon />
                              )}
                            </IconButton>
                          </InputAdornment>
                        ),
                      }}
                    />
                  </Grid>
                  <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                    <Typography
                      variant="subtitle1"
                      sx={{ mb: 1, fontWeight: "medium" }}
                    >
                      Confirm Password
                    </Typography>
                    <TextField
                      fullWidth
                      name="confirmPassword"
                      type={showConfirmPassword ? "text" : "password"}
                      value={formData.confirmPassword}
                      onChange={handleInputChange}
                      variant="outlined"
                      size="small"
                      error={!!errors.confirmPassword}
                      helperText={errors.confirmPassword}
                      sx={{
                        "& .MuiOutlinedInput-root": {
                          borderRadius: "4px",
                          fontFamily: "Speedee",
                        },
                        "& .MuiInputLabel-root": { fontFamily: "Speedee" },
                      }}
                      InputProps={{
                        endAdornment: (
                          <InputAdornment position="end">
                            <IconButton
                              onClick={() =>
                                setShowConfirmPassword(!showConfirmPassword)
                              }
                              edge="end"
                            >
                              {showConfirmPassword ? (
                                <VisibilityOffIcon />
                              ) : (
                                <VisibilityIcon />
                              )}
                            </IconButton>
                          </InputAdornment>
                        ),
                      }}
                    />
                  </Grid>
                </>
              )}

              <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                <Typography
                  variant="subtitle1"
                  sx={{ mb: 1, fontWeight: "medium" }}
                >
                  Department
                </Typography>
                <FormControl fullWidth size="small" variant="outlined">
                  <InputLabel>Department</InputLabel>
                  <Select
                    name="department_id"
                    value={formData.department_id}
                    onChange={handleInputChange}
                    label="Department"
                    error={!!errors.department_id}
                  >
                    <MenuItem value="" sx={{ fontFamily: "Speedee" }}>
                      Select Department
                    </MenuItem>
                    {departments.map((dept) => (
                      <MenuItem
                        key={dept.id}
                        value={dept.id}
                        sx={{ fontFamily: "Speedee" }}
                      >
                        {dept.name}
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>
              <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                <Typography
                  variant="subtitle1"
                  sx={{ mb: 1, fontWeight: "medium" }}
                >
                  Store / Location
                </Typography>
                <FormControl fullWidth size="small" variant="outlined">
                  <InputLabel>Location</InputLabel>
                  <Select
                    name="location_id"
                    value={formData.location_id}
                    onChange={handleInputChange}
                    label="Location"
                    error={!!errors.location_id}
                  >
                    <MenuItem value="" sx={{ fontFamily: "Speedee" }}>
                      Select Location
                    </MenuItem>
                    {locations.map((loc) => (
                      <MenuItem
                        key={loc.id}
                        value={loc.id}
                        sx={{ fontFamily: "Speedee" }}
                      >
                        {loc.name}
                      </MenuItem>
                    ))}
                  </Select>
                  <FormHelperText error={!!errors.location_id}>
                    {errors.location_id || " "}
                  </FormHelperText>
                </FormControl>
              </Grid>

              <Grid item size={{ xs: 12, sm: 12, md: 6, lg: 6, xl: 6 }}>
                <Typography
                  variant="subtitle1"
                  sx={{ mb: 1, fontWeight: "medium" }}
                >
                  Mobile Number (optional)
                </Typography>
                <TextField
                  fullWidth
                  name="mobile"
                  value={formData.mobile}
                  onChange={handleInputChange}
                  variant="outlined"
                  size="small"
                  placeholder="User mobile number"
                  sx={{
                    "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                  }}
                />
              </Grid>

              <Grid
                item
                size={{ xs: 12, sm: 12, md: 12, lg: 12, xl: 12 }}
                sx={{ display: "flex", gap: 2, justifyContent: "flex-end" }}
              >
                <Button
                  variant="contained"
                  onClick={handleSaveChanges}
                  disabled={buttonLoading}
                  sx={{
                    backgroundColor: "#43B02A",
                    "&:hover": {
                      backgroundColor: "#3a9624",
                    },
                    textTransform: "none",
                    px: 3,
                    display: "flex",
                    alignItems: "center",
                    gap: 1,
                  }}
                >
                  {buttonLoading && (
                    <CircularProgress size={20} sx={{ color: "white" }} />
                  )}
                  {editMode ? "Update User" : "Save Changes"}
                </Button>
                <Button
                  variant="contained"
                  onClick={handleCancel}
                  sx={{
                    backgroundColor: "#C92A20",
                    "&:hover": {
                      backgroundColor: "#b12419",
                    },
                    textTransform: "none",
                    px: 3,
                  }}
                >
                  Cancel
                </Button>
              </Grid>
            </Grid>
          </TabPanel>
        </Paper>
      </Grid>
    </Grid>
  );
};

export default UserManagement;
